INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann die IHK meine Ausbildung ohne Grund kündigen?', 2, '[{"text": "Nein", "correct": true, "because": "IHK kündigt nicht, sie überwacht"}, {"text": "Ja", "correct": false, "because": "Keine Kündigungsbefugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die IHK meinen Ausbildungsvertrag prüfen?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht zur Registrierung"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die IHK für meine Prüfungen zuständig?', 2, '[{"text": "Ja", "correct": true, "because": "Organisiert Abschlussprüfungen"}, {"text": "Nein", "correct": false, "because": "Kernaufgabe der IHK"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich die IHK um Hilfe bitten, wenn der Betrieb mich nicht ausbildet?', 2, '[{"text": "Ja", "correct": true, "because": "IHK schlichtet Konflikte"}, {"text": "Nein", "correct": false, "because": "Unterstützung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Muss ich mich bei der IHK melden?', 2, '[{"text": "Nein", "correct": true, "because": "Betrieb meldet Vertrag"}, {"text": "Ja", "correct": false, "because": "Azubi nicht verantwortlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die IHK meinen Betrieb zwingen, mich besser zu bezahlen?', 2, '[{"text": "Nein", "correct": true, "because": "Vergütung ist Vertragsache"}, {"text": "Ja", "correct": false, "because": "Keine direkte Befugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die IHK verpflichtet, Beratung anzubieten?', 2, '[{"text": "Ja", "correct": true, "because": "Teil ihrer Aufgabe"}, {"text": "Nein", "correct": false, "because": "Pflicht der IHK"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte die IHK meine Prüfung verschieben, wenn ich krank bin?', 2, '[{"text": "Ja", "correct": true, "because": "Bei Nachweis möglich"}, {"text": "Nein", "correct": false, "because": "Flexibilität gegeben"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptaufgabe der IHK in der Ausbildung?', 2, '[{"text": "Prüfungen organisieren", "correct": true, "because": "Kernverantwortung"}, {"text": "Gehalt festlegen", "correct": false, "because": "Nicht ihre Rolle"}, {"text": "Urlaub genehmigen", "correct": false, "because": "Betriebssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, die IHK überprüft uns. Was könnten sie kontrollieren?', 3, '[{"text": "Ausbildungsqualität", "correct": true, "because": "Sicherstellung der Standards"}, {"text": "Kaffeeverbrauch", "correct": false, "because": "Irrelevant"}, {"text": "Bürodeko", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht hat die IHK gegenüber meinem Betrieb?', 2, '[{"text": "Vertrag registrieren", "correct": true, "because": "Pflichtaufgabe"}, {"text": "Betrieb schließen", "correct": false, "because": "Keine Befugnis"}, {"text": "Mitarbeiter einstellen", "correct": false, "because": "Nicht ihre Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, wen ich bei Problemen anspreche. Was sage ich?', 3, '[{"text": "IHK", "correct": true, "because": "Vermittelt bei Konflikten"}, {"text": "Klassenkameraden", "correct": false, "because": "Keine Autorität"}, {"text": "Nachbarn", "correct": false, "because": "Kein Bezug"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat die IHK in der Ausbildung?', 4, '[{"text": "Vertragsprüfung", "correct": true, "because": "Registrierung"}, {"text": "Prüfungsorganisation", "correct": true, "because": "Abschlussprüfungen"}, {"text": "Beratung", "correct": true, "because": "Unterstützung"}, {"text": "Vergütung zahlen", "correct": false, "because": "Betriebssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann die IHK bei Konflikten tun?', 3, '[{"text": "Vermitteln", "correct": true, "because": "Schlichtungsrolle"}, {"text": "Beraten", "correct": true, "because": "Hilfeleistung"}, {"text": "Sanktionen verhängen", "correct": true, "because": "Bei Verstößen"}, {"text": "Urlaub genehmigen", "correct": false, "because": "Nicht zuständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Ärger mit dem Betrieb. Welche Rechte hat die IHK?', 3, '[{"text": "Betrieb überprüfen", "correct": true, "because": "Aufsichtsrolle"}, {"text": "Azubis schützen", "correct": true, "because": "Sicherung der Ausbildung"}, {"text": "Streit schlichten", "correct": true, "because": "Mediationsaufgabe"}, {"text": "Betrieb übernehmen", "correct": false, "because": "Keine Befugnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben hat die IHK für Azubis?', 4, '[{"text": "Prüfungen abnehmen", "correct": true, "because": "Abschluss"}, {"text": "Beratung anbieten", "correct": true, "because": "Unterstützung"}, {"text": "Ausbildungsrahmen überwachen", "correct": true, "because": "Qualitätssicherung"}, {"text": "Pausen regeln", "correct": false, "because": "Betriebssache"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die IHK prüft den Ausbildungsvertrag. b) Sie zahlt meine Vergütung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prüfung ja, Vergütung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die IHK organisiert Prüfungen. b) Sie kann meinen Betrieb schließen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prüfungen ja, Schließung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die IHK berät bei Konflikten. b) Sie stellt meinen Ausbilder ein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beratung ja, Einstellung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die IHK überwacht die Ausbildung. b) Ich muss meine Prüfungen selbst bei der IHK anmelden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überwachung ja, Anmeldung Betrieb"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

